"""Tightens docs/extension_studies.md to what the runs support: the generated-corpus lifecycle and gap comparisons are
described as observed (only the stale levels are matched), the mandate's cybersecurity mechanism is provisional, the
Section 6 tables count distinct memory updates alongside affected requests and records, the claim table says what a
stronger statement would need, and the human check of the judge labels is prepared. Final-state wording only.
Run from the eal-bench root after scratch/section6_v2.py has been run into /tmp/s6.md (path below)."""
import pathlib
import sys

DOC = pathlib.Path("docs/extension_studies.md")
S6 = pathlib.Path(sys.argv[1]) if len(sys.argv) > 1 else None
s = DOC.read_text(encoding="utf-8").replace("\r\n", "\n")


def rep(old: str, new: str) -> None:
    global s
    assert s.count(old) == 1, (s.count(old), old[:100])
    s = s.replace(old, new, 1)


# ---- status
rep("## Status, 2026-09-13", "## Status, 2026-09-14")
rep("Every table is from the final runs; every failure in those runs was judged with the Section 6 method.",
    "Every table is from the final runs; every failure in those runs was judged with the Section 6 method. The judge labels have not been checked by a person; a blind sample for that check is prepared (open item 1).")

